def transform(grid):
    h,w=len(grid),len(grid[0]); border=grid[0][0]
    # Frame bands: every row solid in left frame marks a separator.
    starts=[]; prev=0
    for r in range(1,h):
        if all(v==border for v in grid[r][:5]):
            if r>prev: starts.append((prev,r))
            prev=r
    if prev<h: starts.append((prev,h))
    # Extract colored shapes in right area, bounded by blank separator rows.
    shapes=[]; top=0
    for r in range(h+1):
        boundary=(r==h or all(v==border for v in grid[r][:5]))
        if boundary:
            pts=[(rr,c) for rr in range(top,r) for c in range(6,w) if grid[rr][c]!=0]
            if pts:
                color=grid[pts[0][0]][pts[0][1]]
                minr=min(a for a,b in pts); maxr=max(a for a,b in pts); minc=min(b for a,b in pts); maxc=max(b for a,b in pts)
                sh={(a-minr,b-minc) for a,b in pts}
                shapes.append((color,sh))
            top=r+1
    out=[row[:5] for row in grid]
    for a,b in starts:
        if b-a<2: continue
        holes={(rr-a,cc) for rr in range(a,b) for cc in range(5) if grid[rr][cc]==0 and cc not in (0,4)}
        if not holes: continue
        minr=min(x for x,y in holes); maxr=max(x for x,y in holes); minc=min(y for x,y in holes); maxc=max(y for x,y in holes)
